import { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { useSearchParams } from 'react-router-dom';
import Result from '../components/Result';
import AuthContext from '../context/AuthContext';

function History() {
  const [resumes, setResumes] = useState([]);
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [searchParams] = useSearchParams();
  const initialJobId = searchParams.get('jobId') || '';

  const [filters, setFilters] = useState({
    from: '',
    to: '',
    minScore: '',
    q: '',
    limit: 10,
    jobId: initialJobId
  });

  const [openId, setOpenId] = useState(null);
  const [currentEdit, setCurrentEdit] = useState({});
  const { user } = useContext(AuthContext);

  const STATUS_OPTIONS = ['Not Reviewed', 'Shortlisted', 'Rejected', 'Interview Scheduled', 'Interviewed', 'Offer Extended', 'Hired'];

  useEffect(() => {
    load();
  }, [page, filters]);

  async function load() {
    setLoading(true);
    try {
      const params = { page, limit: filters.limit };
      if (filters.minScore) params.minScore = filters.minScore;
      if (filters.from) params.from = filters.from;
      if (filters.to) params.to = filters.to;
      if (filters.q) params.q = filters.q;
      if (filters.jobId) params.jobId = filters.jobId;

      const res = await axios.get('/api/resume/my', { params, withCredentials: true });
      setResumes(res.data.data);
      setTotal(res.data.total || res.data.data?.length || 0);
      setPages(res.data.pages || 1);
      setOpenId(null);
      setCurrentEdit({});
    } catch (err) {
      console.error('Load error:', err);
      alert('Failed to load history');
    } finally {
      setLoading(false);
    }
  }

  async function updateStatus(id, newStatus, note = '') {
    try {
      const payload = { status: newStatus, note: note || 'Quick action' };
      const res = await axios.post(`/api/resume/${id}/status`, payload, { withCredentials: true });
      const updated = res.data.data;
      setResumes(prev => prev.map(r => r._id === id ? updated : r));
    } catch (err) {
      console.error('Status update error:', err);
      alert('Failed to update status');
    }
  }

  function getRecommendation(score) {
    if (score >= 85) return { label: 'Top Pick', class: 'score-good' };
    if (score >= 70) return { label: 'Highly Recommended', class: 'bg-primary' };
    if (score >= 50) return { label: 'Potential Match', class: 'score-warn' };
    return { label: 'Low Match', class: 'score-bad' };
  }

  return (
    <div className="page mt-0">
      <section className="bg-slate-50 pt-16 pb-12 border-b border-border-light">
        <div className="container">
          <div className="flex justify-between items-end">
            <div>
              <h1 className="text-2xl mb-2">Analysis <span className="text-accent">Archive</span></h1>
              <p className="muted">Historical tracking of candidate compatibility and workforce readiness.</p>
            </div>
            {user?.role === 'recruiter' && (
              <div className="flex items-center gap-3">
                <div className="w-2 h-2 rounded-full bg-accent animate-pulse" />
                <span className="text-[10px] font-black uppercase tracking-widest text-accent">Recruiter Intelligence Enabled</span>
              </div>
            )}
          </div>
        </div>
      </section>

      <div className="container py-16">
        <section className="card mb-12" style={{ padding: '32px' }}>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-8 items-end">
            <div className="space-y-2">
              <label className="text-[10px] uppercase font-black tracking-widest muted">Min Compatibility</label>
              <input
                type="number"
                className="form-input"
                style={{ width: '100%' }}
                value={filters.minScore}
                onChange={(e) => setFilters({ ...filters, minScore: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] uppercase font-black tracking-widest muted">Ingestion Date</label>
              <input
                type="date"
                className="form-input"
                style={{ width: '100%' }}
                value={filters.startDate}
                onChange={(e) => setFilters({ ...filters, startDate: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] uppercase font-black tracking-widest muted">Semantic Search</label>
              <input
                type="text"
                className="form-input"
                style={{ width: '100%' }}
                placeholder="Keywords or skills..."
                value={filters.search}
                onChange={(e) => setFilters({ ...filters, search: e.target.value })}
              />
            </div>
            <div className="flex gap-3">
              <button className="btn btn-primary flex-1" onClick={() => setPage(1)}>Execute Filter</button>
              <button className="btn btn-ghost" onClick={() => setFilters({ minScore: '', startDate: '', search: '', limit: 10, jobId: '' })}>Reset</button>
            </div>
          </div>
        </section>

        <div className="space-y-8">
          <div className="flex justify-between items-center mb-4">
            <span className="text-[10px] font-black uppercase tracking-widest muted">{total} Intelligence Profiles Found</span>
          </div>

          {resumes.map((r, index) => {
            const rec = getRecommendation(r.score || 0);
            return (
              <div key={r._id} className="card overflow-hidden" style={{ padding: 0 }}>
                <div className="flex flex-col md:flex-row">
                  <div className="w-full md:w-56 p-8 flex flex-col items-center justify-center text-center bg-slate-50 border-r border-border-light">
                    <span className="text-[10px] uppercase font-black tracking-widest muted mb-4">Affinity Index</span>
                    <div className="text-4xl font-black mb-2" style={{ color: r.score >= 70 ? 'var(--success)' : (r.score >= 40 ? 'var(--warning)' : 'var(--danger)') }}>
                      {Math.round(r.score || 0)}%
                    </div>
                    <span className={`badge px-3 py-1 ${rec.class}`} style={{ fontSize: '9px' }}>
                      {rec.label}
                    </span>
                  </div>

                  <div className="flex-1 p-8">
                    <div className="flex justify-between items-start mb-6">
                      <div className="flex items-center gap-4">
                        <span className="text-sm font-black muted opacity-30">#{index + 1 + (page - 1) * filters.limit}</span>
                        <div>
                          <h4 className="text-lg font-black mb-1">{r.fileName?.split('-')[1] || 'Candidate Resume'}</h4>
                          <p className="small muted font-bold uppercase tracking-tight">System Ref: {r._id?.slice(-8).toUpperCase()}</p>
                        </div>
                      </div>
                      <div className="flex flex-col items-end gap-2">
                        <span className={`badge ${r.interviewStatus === 'Shortlisted' ? 'bg-success' : 'bg-secondary'}`} style={{ fontSize: '10px' }}>
                          {r.interviewStatus}
                        </span>
                        {r.jobId?.title && <span className="text-[10px] font-bold uppercase tracking-widest text-accent">Req: {r.jobId.title}</span>}
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8 pb-8 border-b border-border-light">
                      <div>
                        <span className="block text-[10px] muted uppercase font-black mb-3">Core Matches</span>
                        <div className="flex flex-wrap gap-1.5">
                          {(r.matchedSkills || []).slice(0, 6).map((s, i) => (
                            <span key={i} className="chip" style={{ fontSize: '10px', padding: '5px 10px' }}>{s}</span>
                          ))}
                        </div>
                      </div>
                      <div>
                        <span className="block text-[10px] muted uppercase font-black mb-3">Analysis Actions</span>
                        <p className="small muted italic font-medium">Ready for recruiter decision and deep-dive review.</p>
                      </div>
                    </div>

                    <div className="flex justify-between items-center">
                      <span className="text-[10px] muted uppercase font-black tracking-tighter">Applied {new Date(r.createdAt).toLocaleDateString()}</span>
                      <div className="flex gap-3">
                        <button className="btn btn-ghost py-2 text-xs" onClick={() => setOpenId(openId === r._id ? null : r._id)}>
                          {openId === r._id ? 'Close Profile' : 'Access Analytics'}
                        </button>

                        {['recruiter', 'admin'].includes(user?.role) && r.interviewStatus === 'Not Reviewed' && (
                          <div className="flex gap-2">
                            <button className="btn btn-primary py-2 text-xs" style={{ background: 'var(--success)' }} onClick={() => updateStatus(r._id, 'Shortlisted')}>Shortlist</button>
                            <button className="btn btn-ghost py-2 text-xs" style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }} onClick={() => updateStatus(r._id, 'Rejected')}>Reject</button>
                          </div>
                        )}
                      </div>
                    </div>

                    {openId === r._id && (
                      <div className="mt-8 pt-8 border-t border-border-light animate-in slide-in-from-bottom-2">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                          <div className="space-y-4">
                            <h5 className="flex items-center gap-2 text-xs font-black uppercase tracking-tight">
                              <div className="w-1.5 h-1.5 rounded-full bg-success" /> Verified Strengths
                            </h5>
                            <div className="flex flex-wrap gap-2">
                              {(r.matchedSkills || []).map((s, i) => <span key={i} className="chip">{s}</span>)}
                            </div>
                          </div>
                          <div className="space-y-4">
                            <h5 className="flex items-center gap-2 text-xs font-black uppercase tracking-tight">
                              <div className="w-1.5 h-1.5 rounded-full bg-danger" /> Performance Gaps
                            </h5>
                            <div className="flex flex-wrap gap-2">
                              {(r.missingSkills || []).map((s, i) => <span key={i} className="chip missing">{s}</span>)}
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        <div className="flex justify-center items-center gap-6 py-16 border-t border-border-light mt-12">
          <button className="btn btn-ghost" disabled={page === 1} onClick={() => setPage(p => p - 1)}>Prev Page</button>
          <span className="text-sm font-black uppercase tracking-widest muted">Page <span className="text-primary">{page}</span> of {Math.ceil(total / filters.limit)}</span>
          <button className="btn btn-ghost" disabled={page >= Math.ceil(total / filters.limit)} onClick={() => setPage(p => p + 1)}>Next Page</button>
        </div>
      </div>
    </div>
  );
}

export default History;
